    "title": "Central Bank of India Vacancy 2025 – Faculty, Attendant & Other | Last Date 16 August 2025",
    "slug": "central-bank-of-india-vacancy-2025-faculty-attendant-other-last-date-16-august-2025",
    "org": "Central Bank of India",
    "sector": "Banking",
