    "content_html": "n<h2 class=\"wp-block-heading\">Central Bank of India Recruitment 2025 – Faculty, Attendant एवं अन्य पद</h2>nnnn<p><strong>पोस्ट की तारीख:</strong> 02 अगस्त 2025<br><strong>कुल रिक्तियां:</strong> उल्लेख नहीं<br><strong>आवेदन का प्रकार:</strong> ऑफलाइन फॉर्म</p>nnnn<h3 class=\"wp-block-heading\">संक्षिप्त जानकारी</h3>nnnn<p>Central Bank of India ने Faculty, Attendant एवं अन्य पदों के लिए भर्ती अधिसूचना जारी की है। इच्छुक और पात्र उम्मीदवार, जो सभी योग्यता मानदंड पूरे करते हैं, वे अधिसूचना पढ़कर आवेदन कर सकते हैं।</p>nnnn<h3 class=\"wp-block-heading\">भर्ती संगठन : <strong>Central Bank of India</strong></h3>nnnn<p><strong>आवेदन की अंतिम तिथि:</strong> 16 अगस्त 2025</p>nnnn<h3 class=\"wp-block-heading\">आयु सीमा</h3>nnnn<ul class=\"wp-block-list\">n<li>न्यूनतम आयु: <strong>22 वर्ष</strong></li>nnnn<li>अधिकतम आयु: <strong>40 वर्ष</strong></li>nnnn<li>आयु में छूट नियमानुसार लागू होगी।</li>n</ul>nnnn<h3 class=\"wp-block-heading\">शैक्षणिक योग्यता</h3>nnnn<ul class=\"wp-block-list\">n<li>Graduate</li>nnnn<li>10वीं पास</li>nnnn<li>Any Post Graduate</li>nnnn<li>MSW (Master of Social Work)</li>nnnn<li>7वीं पास</li>n</ul>nnnn<h3 class=\"wp-block-heading\">वेतनमान</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>Faculty:</strong> ₹20,000/- प्रति माह</li>nnnn<li><strong>Attendant:</strong> ₹8,000/- प्रति माह</li>nnnn<li><strong>Watchman-cum-Gardener:</strong> ₹6,000/- प्रति माह</li>n</ul>nnnn<h3 class=\"wp-block-heading\">आवेदन शुल्क : <em>कोई आवेदन शुल्क नहीं है।</em></h3>nnnn<h3 class=\"wp-block-heading\">आवेदन प्रक्रिया</h3>nnnn<ol class=\"wp-block-list\">n<li>आधिकारिक अधिसूचना डाउनलोड करें।</li>nnnn<li>आवेदन पत्र भरें और आवश्यक दस्तावेज़ संलग्न करें।</li>nnnn<li>निर्धारित पते पर ऑफलाइन भेजें।</li>n</ol>nnnn<h3 class=\"wp-block-heading\">महत्वपूर्ण लिंक</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>Official Notification:</strong> <a href=\"https://www.centralbankofindia.co.in/en/recruitments\" data-type=\"link\" data-id=\"https://www.centralbankofindia.co.in/en/recruitments\">Click Here</a></li>nnnn<li><strong>Application Form Download:</strong> <a href=\"https://www.centralbankofindia.co.in/sites/default/files/2025-07/ezyzip_0.zip\" data-type=\"link\" data-id=\"https://www.centralbankofindia.co.in/sites/default/files/2025-07/ezyzip_0.zip\">Click Here</a></li>n</ul>nnnn<p></p>n",
