    "content_html": "n<h2 class=\"wp-block-heading\">BOBCAPS मैनेजर भर्ती 2025 – ऑफलाइन आवेदन करें</h2>nnnn<p><strong>पोस्ट का नाम:</strong> मैनेजर (Secretary)<br><strong>पोस्ट तिथि:</strong> 05-08-2025<br><strong>कुल रिक्तियां:</strong> उल्लेखित नहीं<br><strong>आवेदन की अंतिम तिथि:</strong> 26-08-2025</p>nnnn<h3 class=\"wp-block-heading\"><strong>संक्षिप्त जानकारी:</strong></h3>nnnn<p>BOB Capital Markets (BOBCAPS) ने <strong>मैनेजर (Manager) पद</strong> के लिए भर्ती अधिसूचना जारी की है। इच्छुक और पात्र उम्मीदवार, जो निर्धारित योग्यता मानदंड को पूरा करते हैं, वे अधिसूचना पढ़कर ऑफलाइन आवेदन कर सकते हैं।</p>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>महत्वपूर्ण तिथियां</strong></h3>nnnn<ul class=\"wp-block-list\">n<li><strong>आवेदन करने की अंतिम तिथि:</strong> 26 अगस्त 2025</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>आयु सीमा</strong></h3>nnnn<ul class=\"wp-block-list\">n<li>आयु सीमा अधिसूचना में उल्लेखित नहीं है।</li>nnnn<li>आरक्षण नियमों के अनुसार आयु में छूट लागू होगी (यदि लागू हो)।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>शैक्षिक योग्यता</strong></h3>nnnn<ul class=\"wp-block-list\">n<li>उम्मीदवार <strong>स्नातक (Graduate)</strong> होना अनिवार्य है।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>आवेदन शुल्क</strong></h3>nnnn<ul class=\"wp-block-list\">n<li>कोई आवेदन शुल्क निर्धारित नहीं।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>वेतनमान</strong></h3>nnnn<ul class=\"wp-block-list\">n<li>वेतनमान और अन्य भत्ते BOB Capital Markets के नियमों के अनुसार होंगे।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\"><strong>कैसे आवेदन करें</strong></h3>nnnn<ol class=\"wp-block-list\">n<li>आधिकारिक अधिसूचना डाउनलोड करें और ध्यान से पढ़ें।</li>nnnn<li>आवेदन पत्र को निर्धारित प्रारूप में भरें।</li>nnnn<li>आवश्यक दस्तावेज़ संलग्न कर निर्धारित पते पर भेजें।</li>n</ol>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<p><strong>महत्वपूर्ण लिंक:</strong></p>nnnn<ul class=\"wp-block-list\">n<li>📄 <a href=\"https://www.bobcaps.in/media/2lwdj3u5/jd-secretary.pdf\">https://www.bobcaps.in/media/2lwdj3u5/jd-secretary.pdf</a></li>n</ul>nnnn<p></p>n",
