    "content_html": "n<h2 class=\"wp-block-heading\">यूको बैंक मुख्य जोखिम अधिकारी भर्ती 2025 – ऑनलाइन आवेदन करें </h2>nnnn<p><strong>यूनाइटेड कमर्शियल बैंक (UCO Bank)</strong> ने <strong>मुख्य जोखिम अधिकारी (Chief Risk Officer)</strong> पद पर भर्ती के लिए आधिकारिक अधिसूचना जारी की है। इच्छुक और योग्य उम्मीदवार <strong>12 अगस्त 2025</strong> से <strong>02 सितंबर 2025</strong> तक ऑनलाइन आवेदन कर सकते हैं।</p>nnnn<p><strong>📅 अद्यतन तिथि:</strong> 12 अगस्त 2025</p>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📌 भर्ती का संक्षिप्त विवरण</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>संस्था का नाम:</strong> यूको बैंक (UCO Bank)</li>nnnn<li><strong>पद का नाम:</strong> मुख्य जोखिम अधिकारी (Chief Risk Officer)</li>nnnn<li><strong>कुल पद:</strong> 01</li>nnnn<li><strong>आवेदन प्रकार:</strong> ऑनलाइन</li>nnnn<li><strong>आधिकारिक वेबसाइट:</strong> <a class=\"\" href=\"https://ucobank.com\">ucobank.com</a></li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📝 शैक्षिक योग्यता</h3>nnnn<ul class=\"wp-block-list\">n<li>किसी मान्यता प्राप्त विश्वविद्यालय से <strong>स्नातक डिग्री</strong></li>nnnn<li>साथ में इनमें से कोई एक प्रोफेशनल सर्टिफिकेशन:n<ol class=\"wp-block-list\">n<li><strong>Financial Risk Management (FRM)</strong> – ग्लोबल एसोसिएशन ऑफ़ रिस्क प्रोफेशनल्स (GARP) से</li>nnnn<li><strong>Professional Risk Management (PRM)</strong> – PRMIA Institute से</li>n</ol>n</li>nnnn<li>या, <strong>CRO के रूप में न्यूनतम 2 वर्ष का अनुभव</strong> ऐसे नियामित ऋणदाता संस्थान में, जहां CRO की नियुक्ति बोर्ड अनुमोदन के साथ अनिवार्य हो।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">🎯 आयु सीमा</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>न्यूनतम आयु:</strong> 40 वर्ष</li>nnnn<li><strong>अधिकतम आयु:</strong> 57 वर्ष</li>nnnn<li><strong>आयु में छूट:</strong> नियमानुसार</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">💰 आवेदन शुल्क</h3>nnnn<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>श्रेणी</th><th>शुल्क</th></tr></thead><tbody><tr><td>सभी अन्य उम्मीदवार</td><td>₹800/-</td></tr><tr><td>SC / ST / PWBD</td><td>₹100/-</td></tr></tbody></table></figure>nnnn<h3 class=\"wp-block-heading\">📅 महत्वपूर्ण तिथियां</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>आवेदन प्रारंभ तिथि:</strong> 12 अगस्त 2025</li>nnnn<li><strong>आवेदन की अंतिम तिथि:</strong> 02 सितंबर 2025</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">💵 वेतनमान</h3>nnnn<ul class=\"wp-block-list\">n<li>वेतन उम्मीदवार की <strong>योग्यता, अनुभव, उपयुक्तता और मार्केट बेंचमार्क</strong> के आधार पर तय होगा।</li>nnnn<li>चयनित उम्मीदवार को किसी भी प्रकार का <strong>स्टाफ लाभ/स्कीम</strong> नहीं मिलेगा।</li>nnnn<li>आयकर, प्रोफेशनल टैक्स और अन्य करों का भुगतान उम्मीदवार स्वयं करेगा।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📊 रिक्तियों का विवरण</h3>nnnn<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>पद का नाम</th><th>कुल पद</th></tr></thead><tbody><tr><td>मुख्य जोखिम अधिकारी</td><td>01</td></tr></tbody></table></figure>nnnn<h3 class=\"wp-block-heading\">📂 आवेदन प्रक्रिया</h3>nnnn<ol class=\"wp-block-list\">n<li><a class=\"\" href=\"https://ucobank.com\">ucobank.com</a> पर जाएं।</li>nnnn<li>भर्ती अनुभाग में \"Chief Risk Officer Recruitment 2025\" लिंक खोलें।</li>nnnn<li>पंजीकरण करें और ऑनलाइन आवेदन फॉर्म भरें।</li>nnnn<li>आवश्यक दस्तावेज़ अपलोड करें।</li>nnnn<li>शुल्क का ऑनलाइन भुगतान करें।</li>nnnn<li>आवेदन सबमिट कर प्रिंटआउट सुरक्षित रखें।</li>n</ol>n",
