    "content_html": "n<h2 class=\"wp-block-heading\">महाराष्ट्र स्टेट को-ऑपरेटिव बैंक सहकारी इंटर्न भर्ती 2025 – ऑफलाइन आवेदन करें (16 पद)</h2>nnnn<p><strong>महाराष्ट्र स्टेट को-ऑपरेटिव बैंक (MSC Bank)</strong> ने <strong>16 सहकारी इंटर्न (Cooperative Intern)</strong> पदों पर भर्ती के लिए आधिकारिक अधिसूचना जारी की है। इच्छुक और योग्य उम्मीदवार <strong>22 जुलाई 2025</strong> से <strong>26 अगस्त 2025</strong> तक ऑफलाइन आवेदन कर सकते हैं।</p>nnnn<p><strong>📅 अद्यतन तिथि:</strong> 12 अगस्त 2025</p>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📌 भर्ती का संक्षिप्त विवरण</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>संस्था का नाम:</strong> महाराष्ट्र स्टेट को-ऑपरेटिव बैंक (MSC Bank)</li>nnnn<li><strong>पद का नाम:</strong> सहकारी इंटर्न (Cooperative Intern)</li>nnnn<li><strong>कुल पद:</strong> 16</li>nnnn<li><strong>आवेदन प्रकार:</strong> ऑफलाइन</li>nnnn<li><strong>आधिकारिक वेबसाइट:</strong> <a class=\"\" href=\"https://mscbank.com\">mscbank.com</a></li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📝 शैक्षिक योग्यता</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>MBA</strong> या <strong>02 वर्ष का पोस्ट ग्रेजुएट डिप्लोमा इन मैनेजमेंट (PGDM)</strong> निम्न में से किसी एक विषय में:n<ul class=\"wp-block-list\">n<li>मार्केटिंग मैनेजमेंट</li>nnnn<li>को-ऑपरेटिव मैनेजमेंट</li>nnnn<li>एग्री बिजनेस मैनेजमेंट</li>nnnn<li>ग्रामीण विकास प्रबंधन</li>n</ul>n</li>nnnn<li>डिग्री <strong>AICTE / UGC</strong> मान्यता प्राप्त संस्थान से होनी चाहिए।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">🎯 आयु सीमा <em>(30-06-2025 के अनुसार)</em></h3>nnnn<ul class=\"wp-block-list\">n<li><strong>न्यूनतम आयु:</strong> 21 वर्ष</li>nnnn<li><strong>अधिकतम आयु:</strong> 30 वर्ष</li>nnnn<li><strong>आयु में छूट:</strong> नियमानुसार</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">💰 आवेदन शुल्क</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>उल्लेख नहीं</strong> (नोटिफिकेशन देखें)</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📅 महत्वपूर्ण तिथियां</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>आवेदन प्रारंभ तिथि:</strong> 22 जुलाई 2025</li>nnnn<li><strong>आवेदन की अंतिम तिथि:</strong> 26 अगस्त 2025 (शाम 5:00 बजे तक)</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">💵 वेतनमान</h3>nnnn<ul class=\"wp-block-list\">n<li>चयनित उम्मीदवार को <strong>₹25,000/- प्रति माह</strong> (संयुक्त वेतन) दिया जाएगा, जो संबंधित राज्य सहकारी बैंक / जिला केंद्रीय सहकारी बैंकों द्वारा भुगतान किया जाएगा।</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📊 रिक्तियों का विवरण</h3>nnnn<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>पद का नाम</th><th>कुल पद</th></tr></thead><tbody><tr><td>सहकारी इंटर्न</td><td>16</td></tr></tbody></table></figure>nnnn<h3 class=\"wp-block-heading\">📂 आवेदन प्रक्रिया</h3>nnnn<ol class=\"wp-block-list\">n<li><a class=\"\" href=\"https://mscbank.com\">mscbank.com</a> से <strong>आवेदन प्रपत्र</strong> डाउनलोड करें।</li>nnnn<li>आवेदन पत्र को सही-सही भरें और आवश्यक दस्तावेज़ संलग्न करें।</li>nnnn<li>भरे हुए आवेदन को अधिसूचना में दिए गए पते पर अंतिम तिथि से पहले भेजें।</li>n</ol>n",
