    "content_html": "n<h2 class=\"wp-block-heading\">रिज़र्व बैंक ऑफ इंडिया (RBI) – बैंक मेडिकल कंसल्टेंट भर्ती 2025</h2>nnnn<p>रिज़र्व बैंक ऑफ इंडिया (RBI) ने <strong>बैंक मेडिकल कंसल्टेंट</strong> पदों के लिए भर्ती नोटिफिकेशन जारी किया है। इच्छुक और योग्य उम्मीदवार <strong>ऑफलाइन आवेदन</strong> कर सकते हैं।</p>nnnn<p><strong>आधिकारिक वेबसाइट:</strong> <a class=\"\" href=\"https://www.rbi.org.in/\">rbi.org.in</a></p>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">📅 महत्वपूर्ण तिथियाँ</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>ऑनलाइन/ऑफलाइन आवेदन शुरू होने की तारीख:</strong> 09 जुलाई 2025</li>nnnn<li><strong>आवेदन की अंतिम तारीख:</strong> 28 अगस्त 2025</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">🎯 पात्रता मानदंड</h3>nnnn<ul class=\"wp-block-list\">n<li><strong>शैक्षिक योग्यता:</strong> MBBS डिग्री धारक</li>nnnn<li><strong>उम्र सीमा:</strong> नोटिफिकेशन में निर्दिष्ट नहीं</li>n</ul>nnnn<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>nnnn<h3 class=\"wp-block-heading\">💼 पद विवरण</h3>nnnn<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>पद का नाम</th><th>कुल पद</th></tr></thead><tbody><tr><td>पार्ट टाइम बैंक मेडिकल कंसल्टेंट</td><td>03</td></tr></tbody></table></figure>nnnn<h3 class=\"wp-block-heading\">📝 आवेदन प्रक्रिया</h3>nnnn<ol class=\"wp-block-list\">n<li>आधिकारिक RBI वेबसाइट से भर्ती नोटिफिकेशन डाउनलोड करें।</li>nnnn<li>नोटिफिकेशन में दिए गए <strong>ऑफलाइन आवेदन फॉर्म</strong> को भरें।</li>nnnn<li>आवश्यक दस्तावेजों के साथ आवेदन फॉर्म भेजें।</li>nnnn<li>आवेदन शुल्क (यदि कोई हो) का ध्यान रखें।</li>n</ol>nnnn<p><strong>ध्यान दें:</strong></p>nnnn<ul class=\"wp-block-list\">n<li>आवेदन करने से पहले पात्रता सुनिश्चित करें।</li>nnnn<li>अधूरा या गलत आवेदन रिजेक्ट किया जा सकता है।</li>n</ul>n",
